      hu: ["Az Emírségek első UNESCO Világörökségi helyszíne 2011 óta.", "Több mint 147 000 datolyapálma található a területen.", "Körülbelül 100 különböző pálmafajtát termesztenek itt.", "A terület öntözését az ősi falaj-rendszer biztosítja.", "Az oázis teljes kiterjedése eléri az 1200 hektárt.", "Évezredek óta folyamatosan lakott mezőgazdasági terület."],
      ro: ["Primul sit UNESCO din Emiratele Arabe Unite (din 2011).", "Găzduiește peste 147.000 de palmieri de curmal maturi.", "Include peste 100 de varietăți diferite de curmali.", "Utilizează sistemul de irigații falaj, vechi de milenii.", "Acoperă o suprafață vastă de aproximativ 1.200 de hectare.", "Dispune de un Centru Eco-Vizitatori cu expoziții hi-tech."],
      en: ["First UNESCO World Heritage site in the UAE, listed in 2011.", "Home to more than 147,000 mature date palm trees.", "Cultivates approximately 100 different varieties of dates.", "Features the ancient and sustainable falaj irrigation network.", "Spans a total area of 1,200 hectares in Al Ain's center.", "A living agricultural site inhabited for over 4,000 years."],
